{
    "etc/nginx/conf.d/default-ssl.conf": {
        "parser": "file",
        "find": {
            "  listen ": "  listen {{server.build.env.HTTPS_PORT}} ssl;",
            "  set $port ": "  set $port \"{{server.build.env.HTTPS_PORT}}\";"
        }
    },
    "etc/nginx/conf.d/default.conf": {
        "parser": "file",
        "find": {
            "  listen ": "  listen {{server.build.env.HTTP_PORT}};",
            "  set $port ": "  set $port \"{{server.build.env.HTTP_PORT}}\";"
        }
    },
    "etc/nginx/conf.d/production.conf": {
        "parser": "file",
        "find": {
            "  listen ": "  listen {{server.build.default.port}} default;"
        }
    }
}
